import json
with open('/app/resources/treasury_bulletin_2010_09.json', 'r') as f:
    data = json.load(f)

# Find keys related to public debt securities
def find_keys(d, path=''):
    if isinstance(d, dict):
        for k, v in d.items():
            new_path = f'{path}.{k}' if path else k
            if 'public' in k.lower() and 'debt' in k.lower():
                print(f'Found: {new_path}')
            find_keys(v, new_path)
    elif isinstance(d, list):
        if d and isinstance(d[0], dict):
            find_keys(d[0], f'{path}[0]')

find_keys(data)
